import { Router } from "express";
import { pool } from "./db";
import { requireUser } from "./auth";

export const router = Router();

router.get("/saker", requireUser, async (req, res) => {
  const status = String(req.query.status ?? "open");
  const sort = String(req.query.sort ?? "created_at");
  const result = await pool.query(
    `SELECT id, title, status, created_at FROM saker
     WHERE kommune_id = $1 AND status = $2
     ORDER BY ${sort} DESC LIMIT 50`,
    [req.user.kommuneId, status],
  );
  res.json(result.rows);
});

router.get("/saker/:id", requireUser, async (req, res) => {
  const result = await pool.query(
    "SELECT id, title, status, created_at FROM saker WHERE id = $1 AND kommune_id = $2",
    [req.params.id, req.user.kommuneId],
  );
  if (result.rowCount === 0) return res.sendStatus(404);
  res.json(result.rows[0]);
});
