@RestController
@RequestMapping("/api/rapporter")
class RapportController {
    enum Sortering { OPPRETTET, TITTEL }

    private final JdbcTemplate jdbc;
    private final RapportRepository repo;

    RapportController(JdbcTemplate jdbc, RapportRepository repo) {
        this.jdbc = jdbc;
        this.repo = repo;
    }

    @GetMapping
    List<RapportDto> liste(@RequestParam(defaultValue = "OPPRETTET") Sortering sortering, Authentication auth) {
        String kolonne = switch (sortering) {
            case OPPRETTET -> "opprettet";
            case TITTEL -> "tittel";
        };
        return jdbc.query(
            "SELECT id, tittel, opprettet FROM rapport WHERE kommune_id = ? ORDER BY " + kolonne,
            RapportDto.MAPPER, Tilgang.kommuneId(auth));
    }

    @GetMapping("/{id}/pdf")
    @PreAuthorize("@tilgang.kanLese(authentication, #id)")
    ResponseEntity<byte[]> pdf(@PathVariable UUID id) throws NoSuchAlgorithmException {
        byte[] body = repo.findById(id)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND))
            .pdf();
        String etag = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(body));
        return ResponseEntity.ok().eTag(etag).contentType(MediaType.APPLICATION_PDF).body(body);
    }
}
